  "misconception": {"pack_id": "M13", "wrong": "Каротажная кривая сама показывает породу, и качественного взгляда на неё всегда достаточно.", "right": "Качественные признаки годятся для литологии и простых коллекторов. Для сложных коллекторов и подсчёта запасов нужны расчётные числа.", "claims": ["c1", "c2", "c3"]},
  "data_meaning": {
    "inputs": [
      {"text": "Главные диаграммы геофизического комплекса.", "claims": ["c1"], "hypothesis": false},
      {"text": "Для количественного расчёта: пористость, глинистость, нефтегазонасыщение или параметр насыщения Pп.", "claims": ["c2"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "Литологический разрез (качественно).", "claims": ["c1"], "hypothesis": false},
      {"text": "Числа пористости, нефтегазонасыщения, проницаемости для подсчёта запасов.", "claims": ["c3"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Качественные признаки перестают работать для коллекторов сложнее простейшего межзернового.", "claims": ["c2"], "hypothesis": false}
    ]
  },
  "it_analogy": {"pack_id": "IT03", "analogy": "Качественная интерпретация — правило «на глаз» по дашборду. Количественная — расчёт метрик с числовым порогом.", "breaks_where": "Числовые пороги в ГИС задают петрофизика и экономика района, а не обучение на данных."},
  "now_nuance": null,
  "threshold": {"is_threshold": true, "why": "Нужно различать «узнать по признакам» и «посчитать числа»: запасы считают только по числам, а глаза хватает лишь для простых случаев."},
  "inefficiency": {
    "inputs": [{"text": "Главные диаграммы комплекса ГИС.", "claims": ["c1"], "hypothesis": false}],
    "manual_steps": [{"text": "Сопоставление признаков пород на нескольких диаграммах.", "claims": ["c1"], "hypothesis": false}],
    "judgment_points": [{"text": "Решение, хватит ли качественной интерпретации или нужен расчёт.", "claims": ["c2"], "hypothesis": false}],
    "time": [],
